/// <reference types="vite/client" />
import { setupWorker } from 'msw/browser'
import { handlers } from './handlers'

export { handlers, ADMIN, PRODUCTS } from './handlers'

let started: Promise<unknown> | null = null

/**
 * Starts the MSW worker (ruling R3: every mode, dev and preview). Requests and WebSocket frames that no handler
 * matches — remote entries, manifests, assets — go to the network untouched.
 * Requires `public/mockServiceWorker.js` (generated by `npx msw init public --save`).
 */
export function startMocks(): Promise<unknown> {
  started ??= setupWorker(...handlers).start({
    // msw 3 renamed `onUnhandledRequest` to `onUnhandledFrame` (ruling R3: bypass).
    onUnhandledFrame: 'bypass',
    quiet: true,
    serviceWorker: { url: `${import.meta.env.BASE_URL}mockServiceWorker.js` },
  })
  return started
}
